{
  "identity": {
    "name": "Northwest Roof Restoration, LLC",
    "location": "1028 E Cayman Dr, Meridian, ID 83642 and 728 S Gold Finch Rd, Post Falls, ID 83854",
    "claims": [
      {
        "statement": "The business name is Northwest Roof Restoration, LLC.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/",
        "quote": "Roof repair, new roof installation, and commercial roofing from Northwest Roof Restoration, LLC."
      },
      {
        "statement": "Northwest Roof Restoration is a family-owned roofing company serving Idaho since 2000, under the same ownership since 2003.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/",
        "quote": "Northwest Roof Restoration is a family-owned roofing company that has been roofing in the Boise area and beyond since 2000, under the same ownership since 2003."
      },
      {
        "statement": "The company operates from locations at 1028 E Cayman Dr, Meridian, ID 83642 and 728 S Gold Finch Rd, Post Falls, ID 83854.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/contact-us",
        "quote": "1028 E Cayman Dr, Meridian, ID 83642 728 S Gold Finch Rd, Post Falls, ID 83854"
      }
    ]
  },
  "industry": {
    "industry": "Residential and Commercial Roofing Contracting",
    "activities": [
      "Residential and commercial roof repair and emergency leak/tarping repair",
      "New roof installation and full roof replacement (asphalt shingle, metal, cedar shake, tile, slate)",
      "Commercial flat and membrane roofing (TPO, PVC, EPDM)",
      "Roof maintenance and state-compliance roof inspections and certifications",
      "Storm and wind damage documentation for insurance claims"
    ],
    "claims": [
      {
        "statement": "The company provides roof repair, new roof installation, and commercial roofing services for homes and businesses.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/",
        "quote": "Roof repair, new roof installation, and commercial roofing from Northwest Roof Restoration, LLC."
      },
      {
        "statement": "The company installs and repairs asphalt shingle, metal, flat (TPO and PVC), concrete, and slate roofs.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/",
        "quote": "We install and repair asphalt shingle roofs, metal roofs, flat roofs (TPO and PVC), and other materials like concrete and slate"
      },
      {
        "statement": "The company offers roof inspections and certifications for state regulatory compliance.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/commercial-roofer",
        "quote": "Our company is equipped to certify and inspect all roof types to ensure that they are in compliance with all state regulations."
      },
      {
        "statement": "The company is a roofing contractor and does not advertise HVAC, plumbing, or electrical services on the inspected pages.",
        "label": "inference",
        "sourceUrl": "https://nwroof.net/",
        "quote": null
      }
    ]
  },
  "publicInformation": {
    "officialWebsite": "https://nwroof.net/",
    "claims": [
      {
        "statement": "The company's business hours listed on the contact page are Monday through Friday, 8 AM to 5 PM.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/contact-us",
        "quote": "Monday - Friday: 8 AM - 5 PM"
      },
      {
        "statement": "The company serves Meridian, Boise, Eagle, Nampa, Caldwell, Kuna, Star, Middleton, Post Falls, and Coeur d'Alene (CDA), Idaho.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/service-area",
        "quote": "Boise, ID Caldwell, ID Eagle, ID Kuna, ID Meridian, ID Middleton, ID Star, ID Nampa, ID Post Falls, ID Coeur d'Alene (CDA), ID"
      },
      {
        "statement": "The company offers free estimates via phone, email, or its website request form.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/",
        "quote": "Estimates are free. Call [redacted], email [redacted], or use the Request a Free Estimate form on this site"
      }
    ]
  },
  "licensing": {
    "claims": [
      {
        "statement": "The business identifies itself with the LLC suffix as Northwest Roof Restoration, LLC.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/contact-us",
        "quote": "Since 2000, and under the same ownership since 2003, Northwest Roof Restoration, LLC has been the premier source for roofing services"
      },
      {
        "statement": "The company states it is equipped to certify and inspect roofs for compliance with state regulations.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/",
        "quote": "Our company is equipped to certify and inspect all roofs to ensure that they are in compliance with all state regulations."
      }
    ],
    "limitations": "No specific Idaho contractor registration numbers, state license numbers, or Secretary of State entity filing numbers are displayed on the inspected pages of https://nwroof.net/."
  },
  "existingSoftware": [
    {
      "product": "api.weblium.com / res2.weblium.site / us-central1-weblium-contact-form-app.cloudfunctions.net",
      "purpose": "Website hosting infrastructure and contact form handling",
      "evidence": {
        "statement": "The website references hosts api.weblium.com, res2.weblium.site, and us-central1-weblium-contact-form-app.cloudfunctions.net.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/",
        "quote": "us-central1-weblium-contact-form-app.cloudfunctions.net"
      }
    },
    {
      "product": "embed.tawk.to",
      "purpose": "Website live chat or messaging widget host",
      "evidence": {
        "statement": "The website references the host embed.tawk.to and displays 'Online' in the footer area.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/",
        "quote": "embed.tawk.to"
      }
    },
    {
      "product": "googletagmanager.com (G-RMV3SW1CPG / GTM-5S69S7P)",
      "purpose": "Website analytics and tag management",
      "evidence": {
        "statement": "The website loads scripts and frames from www.googletagmanager.com with IDs G-RMV3SW1CPG and GTM-5S69S7P.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/",
        "quote": "https://www.googletagmanager.com/gtag/js?id=G-RMV3SW1CPG"
      }
    },
    {
      "product": "blog-api.getblog.app",
      "purpose": "Blog content delivery",
      "evidence": {
        "statement": "The website references the host blog-api.getblog.app.",
        "label": "fact",
        "sourceUrl": "https://nwroof.net/",
        "quote": "blog-api.getblog.app"
      }
    }
  ],
  "opportunityEvidence": [
    {
      "statement": "The company collects estimate requests through a web form asking for Name, Phone Number, Service Address, Email, and Comments/Questions, promising to follow up shortly.",
      "label": "fact",
      "sourceUrl": "https://nwroof.net/",
      "quote": "Your Name * Phone Number * Service Address * Email * Comments/Questions Request Estimate We will contact you shortly!"
    },
    {
      "statement": "The company handles emergency storm damage, leak repairs, and insurance claim documentation across two Idaho regions (Treasure Valley and Post Falls).",
      "label": "fact",
      "sourceUrl": "https://nwroof.net/roof-repairs",
      "quote": "When a storm opens up your roof, we offer emergency roof tarping to keep water out until the permanent repair is done"
    }
  ],
  "problems": [
    {
      "problem": "Northwest Roof Restoration, LLC operates in the roofing trade rather than ForgeX's target trades (HVAC, plumbing, and electrical).",
      "label": "fact",
      "basis": "Stated across https://nwroof.net/ that the company is an 'Everything Roofing' contractor offering roof repair, installation, maintenance, and inspections."
    },
    {
      "problem": "Web form estimate inquiries and after-hours storm damage requests may require manual follow-up and routing across the Meridian and Post Falls locations.",
      "label": "hypothesis",
      "basis": "The site uses a basic Weblium contact form (us-central1-weblium-contact-form-app.cloudfunctions.net) and embed.tawk.to, with no visible field-service management or automated scheduling integration on the public pages."
    }
  ],
  "existingSolutions": [
    {
      "solution": "embed.tawk.to widget and Weblium contact form app",
      "addresses": "Basic online visitor chat and web form lead capture",
      "alreadyOwned": true
    },
    {
      "solution": "Roofing-specific CRM / field-service software native lead intake and estimating tools",
      "addresses": "Lead capture, roof measurement/estimating, and insurance claim workflow management",
      "alreadyOwned": false
    }
  ],
  "forgexSolutions": [],
  "feasibility": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended because the company is a roofing contractor outside ForgeX's target segment of HVAC, plumbing, and electrical contractors."
  },
  "aiDelivery": {
    "rating": "not applicable",
    "explanation": "No ForgeX solution is recommended as the company is outside ForgeX's target industry segment."
  },
  "humanReview": [
    "No implementation is recommended; if the founder ever expands into roofing contractors, any roof estimate, insurance documentation, or emergency dispatch commitment would require human review."
  ],
  "risks": [
    {
      "type": "operational",
      "description": "Pursuing a roofing contractor falls outside ForgeX's defined core segment (HVAC, plumbing, and electrical contractors with 10 to 75 staff), which risks misaligning standardized connectors and workflows."
    }
  ],
  "commercial": {
    "supportable": false,
    "value": null,
    "implementationCost": null,
    "assumptions": [
      "The website states 'Estimates are free' and lists no service prices, average ticket values, lead volumes, or employee headcount, so commercial value cannot be calculated from site data."
    ]
  },
