        "url": "https://nwroof.net/service-area",
        "usedFor": "Verification of Treasure Valley and North Idaho cities served."
      },
      {
        "url": "https://nwroof.net/privacy-policy",
        "usedFor": "Verification of data collection disclosures and privacy policy details."
      },
      {
        "url": "https://nwroof.net/roof-repairs",
        "usedFor": "Verification of emergency roof tarping, leak repair, and storm/insurance documentation services."
      },
      {
        "url": "https://nwroof.net/shingle-roofing",
        "usedFor": "Verification of asphalt shingle replacement and repair services."
      }
    ],
    "limitations": [
      "The website does not disclose employee headcount or crew size (cannot confirm whether staff count is between 10 and 75).",
      "The website does not name the owner, executives, or managers.",
      "The website does not disclose state contractor license numbers.",
      "The website does not disclose internal back-office, accounting, or field-service software.",
      "The website does not publish service pricing, average job values, or paid lead generation spend."
    ]
  },
  "qualification": {
    "category": "not a fit",
    "rationale": "ForgeX's target segment is owner-led HVAC, plumbing, and electrical contractors with about 10 to 75 staff who pay for leads. Northwest Roof Restoration, LLC is exclusively a residential and commercial roofing contractor ('Everything Roofing') and does not offer HVAC, plumbing, or electrical services, placing it outside ForgeX's segment."
  }
}
